const token = 'your_secret_token_here';

for (const item of items) {
  const id = item.json.body?.data?.id || '';

  try {
    const response = await this.helpers.httpRequest({
      method: 'GET',
      url: `http://tuyensinhtest.test/api/n8n/leads/${id}/status`,
      headers: {
        'X-N8N-Token': token
      },
      json: true
    });
    item.json.status_response = response;
  } catch (err) {
    item.json.status_error = err.message;
  }
}

return items;

const items = $input.all();
const token = $env.FB_MESSENGER_TOKEN || '';

// Trạm xuất phát
const transformNode = $('Transform FB Message').first();

for (const item of items) {
  // Lấy lại sender_id gốc
  const originalData = transformNode ? transformNode.json.body?.data : {};
  const sender_id = originalData?.sender_id || item.json.sender_id || '';

  // Lấy câu trả lời AI từ payload hiện tại
  const messageText = item.json.message || item.json.body?.data?.message || 'Xin lỗi, hệ thống đang bận.';

  if (!sender_id) {
    item.json.fb_error = 'Thiếu sender_id để gửi tin.';
    continue;
  }

  try {
    const response = await this.helpers.httpRequest({
      method: 'POST',
      url: 'https://graph.facebook.com/v18.0/me/messages',
      qs: { access_token: token },
      body: {
        recipient: { id: sender_id },
        message: { text: messageText }
      },
      json: true
    });
    item.json.fb_reply_response = response;
  } catch (err) {
    item.json.fb_reply_error = err.message;
  }
}

return items;

const items = $input.all();
const token = 'your_secret_token_here';
const transformNode = $('Transform FB Message').first();

for (const item of items) {
  const originalData = transformNode ? transformNode.json.body?.data : {};
  const message = originalData?.message || item.json.message || '';
  const sender_id = originalData?.sender_id || item.json.sender_id || '';
  const is_comment = originalData?.is_comment || false;
  const comment_id = originalData?.comment_id || '';

  try {
    const response = await this.helpers.httpRequest({
      method: 'POST',
      url: 'http://tuyensinhtest.test/api/n8n/rag/answer',
      headers: {
        'X-N8N-Token': token,
        'Content-Type': 'application/json'
      },
      body: {
        question: message,
        sender_id: sender_id,
        is_comment: is_comment,
        comment_id: comment_id
      },
      json: true
    });
    item.json.rag_response = response;
    if (response && response.data && response.data.answer) {
      item.json.message = response.data.answer;
    }
  } catch (err) {
    item.json.rag_error = err.message;
    item.json.message = 'Lỗi khi gọi AI: ' + err.message;
  }
}

return items;

const items = $input.all();
for (const item of items) {
  item.json.sentiment_result = "neutral";
}
return items;

const token = $env.FB_PAGE_ACCESS_TOKEN || '';
const inputItems = $input.all();

if (!token) throw new Error('Thiếu Facebook Page Access Token.');

async function doRequest(options) {
    try {
        return await this.helpers.httpRequest(options);
    } catch (e) {
        const fbErr = e.response && e.response.data ? JSON.stringify(e.response.data) : e.message;
        throw new Error('Lỗi từ Facebook: ' + fbErr + ' | Payload: ' + JSON.stringify(options.body));
    }
}

// Lấy ngrok url tự động
// let ngrokUrl = 'https://examining-civilization-yeast-lang.trycloudflare.com';
let ngrokUrl = '';
try {
  const ngrokRes = await this.helpers.httpRequest({ method: 'GET', url: 'http://127.0.0.1:4040/api/tunnels', json: true });
  if (ngrokRes && ngrokRes.tunnels && ngrokRes.tunnels.length > 0) {
    ngrokUrl = ngrokRes.tunnels[0].public_url;
  }
} catch(e) { console.log('Không lấy được ngrok'); }

for (const item of inputItems) {
  let images = Array.isArray(item.json.content_images)
    ? item.json.content_images.filter(Boolean).slice(0, 5)
    : [];

  // Thay thế domain local thành public ngrok
  images = images.map(img => {
    if (ngrokUrl && img.includes('tuyensinhtest.test')) {
      return img.replace(/http[s]?:\/\/tuyensinhtest\.test/g, ngrokUrl);
    }
    return img;
  });

  const message = String(item.json.facebook_message || '').trim();

  if (!message) throw new Error('Thiếu facebook_message.');
  if (images.length === 0) throw new Error('Nhánh có ảnh nhưng content_images rỗng.');

  if (images.length === 1) {
    item.json.fb_response = await doRequest.call(this, {
      method: 'POST',
      url: 'https://graph.facebook.com/v18.0/me/photos',
      qs: { access_token: token },
      body: { url: images[0], message },
      json: true,
    });
    continue;
  }

  const attachedMedia = [];
  for (const imageUrl of images) {
    const upload = await doRequest.call(this, {
      method: 'POST',
      url: 'https://graph.facebook.com/v18.0/me/photos',
      qs: { access_token: token },
      body: { url: imageUrl, published: false },
      json: true,
    });

    if (upload?.id) attachedMedia.push({ media_fbid: upload.id });
  }

  if (attachedMedia.length === 0) {
    throw new Error('Facebook không trả về media_fbid cho các ảnh đã tải.');
  }

  item.json.fb_response = await doRequest.call(this, {
    method: 'POST',
    url: 'https://graph.facebook.com/v18.0/me/feed',
    qs: { access_token: token },
    body: { message, attached_media: attachedMedia },
    json: true,
  });
}

return inputItems;

const inputItems = $input.all();
const source = $('Data Validator').first().json.body?.data || {};

for (const item of inputItems) {
  const caption = String(item.json.caption || '').trim();
  const hashtags = String(item.json.hashtags || '').trim();
  const articleUrl = String(source.url || '').trim();

  item.json.article_id = source.id || null;
  item.json.article_title = source.title || '';
  item.json.article_url = articleUrl;
  item.json.content_images = Array.isArray(source.content_images) ? source.content_images : [];
  item.json.has_images = Boolean(source.has_images);
  item.json.facebook_message = [caption, articleUrl, hashtags]
    .filter(Boolean)
    .join('\n\n');
